// This style of import is necessary for storybook to automatically generate the documentation for prop types and control interface
import * as React from "react";
import { HTMLAttributes } from "react";
import "./VerticalBarBadge.scss";

// Extend existing React interface Badge.
export interface VerticalBarBadgeProps extends HTMLAttributes<HTMLSpanElement> {
  /**
   * Identifying value for the badge.
   */
  id: string;  
  /**
   * Determines the colour palette of the badge.
   */
  colour?: "primary" | "secondary" | "tertiary" |  "success" | "warning" | "error" | "surface";  
  /**
   * Custom className that can be passed to the element for overriding styling.
   */
  className?: string;  
}

const VerticalBarBadge: React.FC<VerticalBarBadgeProps> = ({
  id,  
  className,  
  colour = "primary",  
}) => {  
    // Create a base class name for the badge
    const badgeClassName = [
      "mpa-vertical-bar-badge",      
      `mpa-vertical-bar-badge-${colour}`,
      className,
    ].join(" ");
  
	return (      
      <span id={id} className={badgeClassName}></span>
	);
};

export default VerticalBarBadge;
